import {socketEditor} from './socket-editor.js';
import {affixHTML} from './affixes.js';
import {bagCards,shopView} from './inventory-ui.js';
import {buy,sell,drawLottery} from './shop.js';
import {socketDiagram} from './socket-ui.js';
import {ACTIVE_GEMS,SUPPORT_GEMS,compileSkill,compatible,gemColor} from './gems.js';
import {CURRENCIES,SOCKET_COLORS,weaponFor,gemSocket,colorFits,EQUIPMENT_SLOTS,SLOT_NAMES,gearType,gearLabel,equipmentStats} from './progression.js';
const socket=(color,text='',locked=false)=>`<span class="socket ${locked?'unlinked':''}" style="--socket:${SOCKET_COLORS[color]?.hex||'#526148'}" title="${SOCKET_COLORS[color]?.name||'未開啟'}孔">${text||color||'×'}</span>`;
export function wallet(g){return `<div class="wallet">${Object.entries(CURRENCIES).map(([id,c])=>`<span><img src="assets/${id}.svg" alt="">${c.name}<b>${g.bag.currency[id]}</b></span>`).join('')}</div>`}
export function buildPanel(game,modal,close,initialTab='equipment'){
 let tab=initialTab,selected=null;
 let craftId=game.equipped.find(Boolean)||game.bag.weapons[0].id;
 function render(message=''){
 if(!game.bag.weapons.some(w=>w.id===craftId))craftId=game.bag.weapons[0].id;
 const scroll=document.querySelector('.build-panel')?.scrollTop||0;
 modal(`<div class="build-panel"><div class="build-heading"><div><span class="eyebrow">INVENTORY / 第 ${game.round}/3 回合 · 第 ${game.wave}/15 波</span><h2>${tab==='equipment'?'裝備與串連':tab==='bag'?'背包':'臨界商店'}</h2></div><button id="closeBuild" class="secondary">完成配置 ↗</button></div>${wallet(game)}<nav class="inventory-tabs" aria-label="行囊分頁">${[['equipment','裝備'],['bag','背包'],['shop','商店']].map(([id,label])=>`<button class="${tab===id?'selected':''}" data-tab="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}<span>金幣 ${game.gold} · 臨界卷 ${game.tickets}</span></nav><p class="trade-message" role="status">${message}</p><section ${tab==='equipment'?'':'hidden'}><div class="socket-legend"><span><i class="legend-chain">∞</i> 金鏈：共享相容輔助</span><span><i>×</i> 斷鏈：輔助不生效</span><span><i>＋</i> 未開孔：先用匠魂石</span></div><p class="build-intro">只有戰利品中的寶石能裝備。點選任一已開啟孔洞，再點寶石即可安裝。所有孔洞不限顏色、不限類型；只有相連且相容的輔助生效。</p><div class="build-notice" role="status">${message||'小怪寶石掉率 5%、Boss 35%；裝備掉率 3% / 80%。地面發光掉落須靠近拾取。每 5 波 Boss 後可改造所有裝備孔洞。'}</div><div class="link-grid">${game.links.map((row,i)=>{
 const w=weaponFor(game,i),a=ACTIVE_GEMS[row.active],stats=compileSkill(row,game.player,game.gemLevels,w);
 return `<section class="link-card" style="--gem-color:${a?.color||'#b6a274'}"><div class="link-number">${SLOT_NAMES[i]}<span>${w?`${w.sockets.length} 孔 · ${w.linked} 孔串連`:'尚未取得裝備'}</span></div><label class="equipment-label">裝備<select data-weapon="${i}">${w?'':'<option value="">尚無裝備</option>'}${game.bag.weapons.filter(v=>gearType(v)===EQUIPMENT_SLOTS[i]).map(v=>`<option value="${v.id}" ${w?.id===v.id?'selected':''} ${game.equipped.some((id,k)=>k!==i&&id===v.id)?'disabled':''}>${gearLabel(v)}</option>`).join('')}</select></label>${w?`<p class="gear-bonus">${gearLabel(w)} · ${w.rarity==='legendary'?'傳說':w.rarity==='epic'?'史詩':w.rarity==='rare'?'稀有':'普通'} · 對應標籤傷害 +${w.power}%</p>${affixHTML(w)}${socketEditor(game,w,row,i,selected)}`:'<p class="active-description">擊殺敵人取得對應裝備後，可在此串連最多四顆任意類型寶石。</p>'}</section>`}).join('')}</div>
 ${game.forgeUnlocked?`<section class="forge-section"><span class="eyebrow">BOSS CLEARED / FORGE</span><h2>重塑你的裝備</h2><p>增孔與連孔必定成功；隨機改色消耗較少，指定改色需要兩顆幻彩石。孔色僅為裝飾，改色不影響寶石與連線。</p><label class="equipment-label">製作目標<select id="forgeWeapon">${game.bag.weapons.map(w=>`<option value="${w.id}" ${w.id===craftId?'selected':''}>${w.name}</option>`).join('')}</select></label>${socketDiagram(game.bag.weapons.find(w=>w.id===craftId),game.links[game.equipped.indexOf(craftId)])}<div class="craft-actions"><button class="secondary" data-craft="socket">增開一孔 · 匠魂石 ×2</button><button class="secondary" data-craft="link">串連下一孔 · 連結石 ×2</button><button class="secondary" data-craft="reroll">全部隨機改色 · 幻彩石 ×1</button></div><div class="target-color"><label>孔位<select id="colorIndex">${game.bag.weapons.find(w=>w.id===craftId).sockets.map((_,i)=>`<option value="${i}">第 ${i+1} 孔</option>`).join('')}</select></label><label>指定顏色<select id="colorValue"><option value="R">紅色</option><option value="G">綠色</option><option value="B">藍色</option></select></label><button class="primary" id="recolor">指定改色 · 幻彩石 ×2</button></div></section>`:'<div class="forge-locked">◇ 工坊尚未開放 · 再擊敗 '+(5-(game.wave-1)%5)+' 波即可製作孔洞</div>'}
 </section><section ${tab==='bag'?'':'hidden'}>${bagCards(game)}<div class="gear-summary">裝備加成：護甲 +${equipmentStats(game).armor} · 移速 +${equipmentStats(game).speed}%<br>最近拾取：${game.lootHistory.map(w=>w.name).join('、')||'尚無掉落'}<br>行囊上限 40 件；滿額時最舊的未裝備物品會轉為 2 顆匠魂石。</div><details class="build-codex"><summary>寶石收藏 · 主動 ${game.bag.active.length} · 輔助 ${game.bag.support.length}</summary><div class="codex-grid">${[...game.bag.active.map(id=>ACTIVE_GEMS[id]),...game.bag.support.map(id=>SUPPORT_GEMS[id])].map(a=>`<div><strong style="color:${SOCKET_COLORS[a.socket]?.hex||'#eae6d3'}">${a.icon} ${a.name}</strong><p>${a.desc}</p></div>`).join('')}</div></details></section><section ${tab==='shop'?'':'hidden'}>${tab==='shop'?shopView(game):''}</section><p class="build-footnote">每局重新開始時，武器、技能與通貨全部重置。僅保留一把朽木杖與烈焰火球。</p></div>`);
 document.querySelector('.build-panel').scrollTop=scroll;document.getElementById('closeBuild').onclick=close;document.querySelectorAll('[data-aura]').forEach(b=>b.onclick=()=>{game.toggleAura(b.dataset.aura);render()});
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelector('.build-panel').scrollTop=0;render();document.querySelector(`[data-tab="${tab}"]`).focus()});
 document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const r=buy(game,b.dataset.buy==='ticket'?'ticket':+b.dataset.buy);render(r.reason)});
 document.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>{const r=sell(game,b.dataset.sell);render(r.reason)});
 const draw=document.getElementById('drawLegend');if(draw)draw.onclick=()=>{const r=drawLottery(game);render(r.reason)};
 document.querySelectorAll('[data-pick-row]').forEach(b=>b.onclick=()=>{selected={row:+b.dataset.pickRow,socket:+b.dataset.pickSocket};render();document.querySelector('.gem-picker')?.scrollIntoView({block:'nearest'})});
 document.querySelectorAll('[data-gem-id]').forEach(b=>b.onclick=()=>{const r=game.install(selected.row,selected.socket,{kind:b.dataset.gemKind,id:b.dataset.gemId});render(r.reason)});
 const remove=document.querySelector('[data-gem-remove]');if(remove)remove.onclick=()=>{const r=game.install(selected.row,selected.socket,null);render(r.reason)};
 document.querySelectorAll('[data-weapon]').forEach(el=>el.onchange=()=>{if(!el.value)return;const r=game.equip(+el.dataset.weapon,el.value);render(r.ok?'裝備已更換；超出孔數的寶石已退回行囊。':r.reason)});
 if(game.forgeUnlocked){document.getElementById('forgeWeapon').onchange=e=>{craftId=e.target.value;render()};document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{const r=game.craft(craftId,b.dataset.craft);render(r.ok?`製作完成：${game.bag.weapons.find(w=>w.id===craftId).sockets.length} 孔已開啟，${game.bag.weapons.find(w=>w.id===craftId).linked} 孔串連。`:r.reason)});document.getElementById('recolor').onclick=()=>{const r=game.craft(craftId,'recolor',{index:+document.getElementById('colorIndex').value,color:document.getElementById('colorValue').value});render(r.reason)}}
 }render();
}
